SELECT id, email, signup_date, credit_limit, age, NTILE(4) OVER (PARTITION BY segment ORDER BY age DESC, id) age_bucket, FIRST_VALUE(credit_limit, TRUE) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_credit_limit, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY country), 4) credit_limit_share, NTILE(10) OVER (ORDER BY age, id) age_bucket_2 FROM customers
